//! dash-schema against what the JS answers (rust/fixtures/golden/dash-schema/*.json, generated by
//! rust/fixtures/gen/dash-schema-golden.mjs from src/dashboard/schema.js and fields.js), and the catalog parts that come
//! from these files (rust/fixtures/golden/dashboard-catalog.json, buildCatalog()).

use std::path::PathBuf;

use dash_schema::fields::{self, registry};
use dash_schema::schema::{self, Field};
use dash_schema::{GuildResources, KeepRefs, Refs};
use indexmap::IndexSet;
use serde_json::{Value, json};

fn golden(name: &str) -> Value {
    let p = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../fixtures/golden").join(name);
    serde_json::from_str(&std::fs::read_to_string(&p).unwrap_or_else(|e| panic!("{}: {e}", p.display()))).unwrap()
}

/// Collects mismatches and fails with the first ones.
#[derive(Default)]
struct Diffs(Vec<String>, usize);

impl Diffs {
    fn eq_str(&mut self, what: impl FnOnce() -> String, ours: &Value, theirs: &Value) {
        self.1 += 1;
        let (a, b) = (ours.to_string(), theirs.to_string());
        if a != b {
            self.0.push(format!("{}\n   rust: {}\n     js: {}", what(), cut(&a), cut(&b)));
        }
    }
    fn finish(self, name: &str) {
        assert!(self.1 > 0, "{name}: nothing compared");
        if !self.0.is_empty() {
            let n = self.0.len();
            let shown: Vec<String> = self.0.into_iter().take(25).collect();
            panic!("{name}: {n} of {} comparisons differ:\n{}", self.1, shown.join("\n"));
        }
        eprintln!("{name}: {} comparisons", self.1);
    }
}

fn cut(s: &str) -> String {
    if s.chars().count() > 400 { format!("{}…", s.chars().take(400).collect::<String>()) } else { s.to_string() }
}

/// No known gaps are left: `datetime` uses bot_util's port of V8's `Date.parse` (legacy forms included; the goldens
/// are generated with `TZ=UTC`, the zone the Rust tests read when `TZ` is unset) and `emoji` uses the exact
/// `\p{RGI_Emoji}` set. Kept as a hook so a future gap is skipped in one place.
fn known_gap(_ty: &str, _probe: &Value, _js_refused: bool, _js_read_a_date: bool) -> bool {
    false
}

fn refs_json(r: &Refs) -> Value {
    serde_json::to_value(r).unwrap()
}

fn stored_refs_json(r: &dash_schema::StoredRefs) -> Value {
    json!({ "channels": r.channels.iter().collect::<Vec<_>>(), "roles": r.roles.iter().collect::<Vec<_>>() })
}

fn synthetic(values: &Value) -> Vec<Field> {
    values["synthetic"].as_array().unwrap().iter().map(|d| Field::from_json(d.clone()).unwrap()).collect()
}

/// The descriptor at a golden path: 'field', 'field.child', 'list[].child' or 'synthetic.name'.
fn descriptor_at(at: &str, synth: &[Field]) -> Field {
    if let Some(name) = at.strip_prefix("synthetic.") {
        return synth.iter().find(|f| f.field() == name).cloned().unwrap();
    }
    let mut parts = at.split('.').map(|p| p.trim_end_matches("[]"));
    let mut d = fields::settings_field(parts.next().unwrap()).unwrap_or_else(|| panic!("no field {at}")).clone();
    for p in parts {
        d = d.child(p).unwrap_or_else(|| panic!("no child {p} in {at}")).clone();
    }
    d
}

#[test]
fn validate_settings_changes_and_storage_per_field_and_probe() {
    let g = golden("dash-schema/settings-changes.json");
    let generic = g["generic"].as_array().unwrap();
    let table = g["table"].as_array().unwrap();
    let sample_row = &g["sampleRow"];
    let mut d = Diffs::default();
    for case in g["cases"].as_array().unwrap() {
        let field = case["field"].as_str().unwrap();
        let probes: Vec<&Value> = generic.iter().chain(case["extra"].as_array().unwrap()).collect();
        for (probe, idx) in probes.iter().zip(case["results"].as_array().unwrap()) {
            let want = &table[idx.as_u64().unwrap() as usize];
            let ty = fields::settings_field(field).unwrap().ty();
            if known_gap(ty, probe, want.get("error").is_some(), false) {
                continue;
            }
            let body = json!({ "changes": { field: probe } });
            let what = || format!("{field} <- {}", cut(&probe.to_string()));
            let theirs = match want.get("error") {
                Some(err) => json!({ "error": err }),
                None => json!({ "ok": want["changes"] }),
            };
            match dash_schema::validate_settings_changes(&body) {
                Ok(v) => {
                    d.eq_str(what, &json!({ "ok": Value::Object(v.changes.clone()) }), &theirs);
                    if want.get("changes").is_none() {
                        continue;
                    }
                    let refs = want.get("refs").cloned().unwrap_or_else(|| json!({ "channels": [], "roles": [] }));
                    d.eq_str(|| format!("{field} refs <- {}", cut(&probe.to_string())), &refs_json(&v.refs), &refs);
                    let stored = Value::Object(dash_schema::to_stored_changes(&v.changes, None));
                    d.eq_str(|| format!("{field} stored <- {}", cut(&probe.to_string())), &stored, &want["stored"]);
                    let on_row = Value::Object(dash_schema::to_stored_changes(&v.changes, Some(sample_row)));
                    let want_row = want.get("storedOnRow").unwrap_or(&want["stored"]);
                    d.eq_str(|| format!("{field} storedOnRow <- {}", cut(&probe.to_string())), &on_row, want_row);
                }
                Err(e) => {
                    let ours = json!({ "error": { "message": e.message, "path": e.path } });
                    d.eq_str(what, &ours, &theirs);
                }
            }
        }
    }
    d.finish("settings changes");
}

#[test]
fn validate_read_and_refs_per_descriptor_and_probe() {
    let g = golden("dash-schema/values.json");
    let synth = synthetic(&g);
    let generic = g["generic"].as_array().unwrap();
    let table = g["table"].as_array().unwrap();
    let mut d = Diffs::default();
    for case in g["cases"].as_array().unwrap() {
        let at = case["at"].as_str().unwrap();
        let desc = descriptor_at(at, &synth);
        let probes: Vec<&Value> = generic.iter().chain(case["extra"].as_array().unwrap()).collect();
        for (probe, idx) in probes.iter().zip(case["results"].as_array().unwrap()) {
            let want = &table[idx.as_u64().unwrap() as usize];
            let js_read_a_date = want["validate"]["ok"].is_string() || (want["read"].is_string() && Some(&want["read"]) != desc.default_value());
            if known_gap(desc.ty(), probe, want["validate"].get("error").is_some(), js_read_a_date) {
                continue;
            }
            let p = || cut(&probe.to_string());
            let mut refs = Refs::default();
            let ours = match schema::validate_value(&desc, probe, None, &mut refs) {
                Ok(v) => json!({ "ok": v }),
                Err(e) => json!({ "error": { "path": e.path, "message": e.message } }),
            };
            d.eq_str(|| format!("validate {at} <- {}", p()), &ours, &want["validate"]);
            if want["validate"].get("ok").is_some() {
                let want_refs = want.get("refs").cloned().unwrap_or_else(|| json!({ "channels": [], "roles": [] }));
                d.eq_str(|| format!("refs {at} <- {}", p()), &refs_json(&refs), &want_refs);
            }
            d.eq_str(|| format!("read {at} <- {}", p()), &schema::read_value(&desc, Some(probe)), &want["read"]);
            let mut stored = dash_schema::StoredRefs::default();
            schema::collect_stored_refs(&desc, Some(probe), &mut stored);
            let want_stored = want.get("storedRefs").cloned().unwrap_or_else(|| json!({ "channels": [], "roles": [] }));
            d.eq_str(|| format!("storedRefs {at} <- {}", p()), &stored_refs_json(&stored), &want_stored);
            let mut keys = IndexSet::new();
            schema::stored_ref_keys(&desc, Some(probe), None, &mut keys);
            let want_keys = want.get("refKeys").cloned().unwrap_or_else(|| json!([]));
            d.eq_str(|| format!("refKeys {at} <- {}", p()), &json!(keys), &want_keys);
        }
    }
    d.finish("values");
}

#[test]
fn rows_read_like_the_js() {
    let g = golden("dash-schema/rows.json");
    let mut d = Diffs::default();
    for (name, case) in g.as_object().unwrap() {
        let row = &case["row"];
        let values = Value::Object(dash_schema::read_settings_values(Some(row)));
        d.eq_str(|| format!("{name}: readSettingsValues"), &values, &case["values"]);
        d.eq_str(|| format!("{name}: collectSettingsRefs"), &stored_refs_json(&dash_schema::collect_settings_refs(Some(row))), &case["refs"]);
        d.eq_str(|| format!("{name}: collectSettingsRefKeys"), &json!(dash_schema::collect_settings_ref_keys(Some(row))), &case["refKeys"]);
        d.eq_str(|| format!("{name}: automodConfigOf"), &dash_schema::automod_config_of(Some(row)), &case["automodConfig"]);
    }
    d.finish("rows");
}

#[test]
fn helpers_match_the_js() {
    let g = golden("dash-schema/helpers.json");
    let mut d = Diffs::default();
    for c in g["words"].as_array().unwrap() {
        d.eq_str(|| format!("word {}", c["input"]), &json!(dash_schema::normalize_automod_word(Some(&c["input"]))), &c["out"]);
    }
    for c in g["domains"].as_array().unwrap() {
        d.eq_str(|| format!("domain {}", c["input"]), &json!(dash_schema::normalize_automod_domain(Some(&c["input"]))), &c["out"]);
    }
    for c in g["escalation"].as_array().unwrap() {
        d.eq_str(|| format!("escalation {}", c["input"]), &dash_schema::normalize_escalation(Some(&c["input"])), &c["out"]);
    }
    for c in g["embedHasContent"].as_array().unwrap() {
        d.eq_str(|| format!("embedHasContent {}", c["input"]), &json!(dash_schema::embed_has_content(&c["input"])), &c["out"]);
    }
    for c in g["channelKind"].as_array().unwrap() {
        let t = c["input"].as_i64().unwrap_or(i64::MIN);
        d.eq_str(|| format!("channelKind {}", c["input"]), &json!(schema::channel_kind(t)), &c["out"]);
    }
    for c in g["refKey"].as_array().unwrap() {
        let ours = schema::ref_key(c["path"].as_str().unwrap(), c["id"].as_str().unwrap());
        d.eq_str(|| format!("refKey {}", c["path"]), &json!(ours), &c["out"]);
    }
    for c in g["isSnowflake"].as_array().unwrap() {
        d.eq_str(|| format!("isSnowflake {}", c["input"]), &json!(schema::is_snowflake(&c["input"])), &c["out"]);
    }
    d.finish("helpers");
}

#[test]
fn rules_refs_lint_and_bodies_match_the_js() {
    let g = golden("dash-schema/rules.json");
    let synth = synthetic(&golden("dash-schema/values.json"));
    let mut d = Diffs::default();

    for c in g["cross"].as_array().unwrap() {
        let changes = c["changes"].as_object();
        let ours = dash_schema::check_cross_fields(Some(&c["row"]), changes);
        d.eq_str(|| format!("cross {} / {}", c["row"], c["changes"]), &json!(ours), &c["out"]);
    }

    let mut res = GuildResources::default();
    for pair in g["resources"]["channels"].as_array().unwrap() {
        res.channels.insert(pair[0].as_str().unwrap().into(), schema::ChannelInfo { kind: pair[1]["kind"].as_str().unwrap().into() });
    }
    for pair in g["resources"]["roles"].as_array().unwrap() {
        let r = &pair[1];
        res.roles.insert(
            pair[0].as_str().unwrap().into(),
            schema::RoleInfo { everyone: r["everyone"] == true, managed: r["managed"] == true, assignable: r["assignable"] == true },
        );
    }
    for c in g["refs"].as_array().unwrap() {
        let refs: Refs = serde_json::from_value(c["refs"].clone()).unwrap();
        let set = |k: &str| c["keep"][k].as_array().into_iter().flatten().map(|v| v.as_str().unwrap().to_string()).collect();
        let keep = KeepRefs { channels: set("keepChannels"), roles: set("keepRoles") };
        let ours = schema::check_refs(&refs, &res, &keep).err().map(|e| json!({ "path": e.path, "message": e.message }));
        d.eq_str(|| format!("checkRefs {}", c["refs"]), &json!(ours), &c["out"]);
    }

    for c in g["assignable"].as_array().unwrap() {
        let descs: Vec<Field> = c["fields"]
            .as_array()
            .unwrap()
            .iter()
            .map(|n| {
                let n = n.as_str().unwrap();
                if c["synthetic"] == true {
                    synth.iter().find(|f| f.field() == n).cloned().unwrap()
                } else {
                    fields::settings_field(n).cloned().unwrap()
                }
            })
            .collect();
        let ours = schema::collect_assignable_roles(&descs, Some(&c["record"]));
        d.eq_str(|| format!("assignable {}", cut(&c["record"].to_string())), &json!(ours), &c["out"]);
    }

    for c in g["lint"].as_array().unwrap() {
        let descs: Vec<Field> = c["fields"].as_array().unwrap().iter().map(|f| Field::from_json(f.clone()).unwrap()).collect();
        d.eq_str(|| format!("lint {}", cut(&c["fields"].to_string())), &json!(schema::lint_descriptors(&descs, "w/")), &c["out"]);
    }

    let sample = golden("dash-schema/settings-changes.json")["sampleRow"].clone();
    for c in g["bodies"].as_array().unwrap() {
        let what = || format!("body {}", cut(&c["body"].to_string()));
        match dash_schema::validate_settings_changes(&c["body"]) {
            Ok(v) => {
                d.eq_str(what, &json!(true), &c["ok"]);
                d.eq_str(what, &Value::Object(v.changes.clone()), &c["changes"]);
                d.eq_str(what, &refs_json(&v.refs), &c["refs"]);
                d.eq_str(what, &Value::Object(dash_schema::to_stored_changes(&v.changes, None)), &c["stored"]);
                let on_row = dash_schema::to_stored_changes(&v.changes, Some(&sample));
                d.eq_str(what, &Value::Object(on_row.clone()), &c["storedOnRow"]);
                let mut merged = sample.as_object().unwrap().clone();
                merged.extend(on_row);
                let cross = dash_schema::check_cross_fields(Some(&Value::Object(merged)), Some(&v.changes));
                d.eq_str(what, &json!(cross), &c["cross"]);
            }
            Err(e) => {
                d.eq_str(what, &json!({ "ok": false, "message": e.message, "path": e.path }), &json!({ "ok": c["ok"], "message": c["message"], "path": c["path"] }));
            }
        }
    }
    d.finish("rules");
}

#[test]
fn catalog_groups_are_reproduced_byte_for_byte() {
    let cat = golden("dashboard-catalog.json");
    let mut d = Diffs::default();
    let general: Vec<Value> = fields::general_groups().iter().map(fields::Group::public_json).collect();
    d.eq_str(|| "general.groups".into(), &Value::Array(general), &cat["general"]["groups"]);
    let modules = cat["modules"].as_object().unwrap();
    assert_eq!(modules.len(), registry().module_groups.len(), "every module is in the catalog");
    for (key, m) in modules {
        let groups: Vec<Value> = fields::module_groups(key).unwrap().iter().map(fields::Group::public_json).collect();
        d.eq_str(|| format!("{key}.groups"), &Value::Array(groups), &m["groups"]);
        // subToggles (catalog.js) are { field, label, description, default } of settings fields.
        for t in m["subToggles"].as_array().unwrap() {
            let f = fields::settings_field(t["field"].as_str().unwrap()).unwrap();
            let ours = json!({ "field": f.field(), "label": f.label(), "description": f.description(), "default": f.default_value() });
            d.eq_str(|| format!("{key} subToggle {}", t["field"]), &ours, t);
        }
    }
    d.finish("catalog");
}
